const sqlite3 = require('sqlite3');
const db = new sqlite3.Database('/workspace/world.db');
db.all(\"SELECT name FROM sqlite_master WHERE type='table'\", (err, tables) => {
  console.log('Tables:', tables);
  tables.forEach(t => {
    db.all('SELECT * FROM ' + t.name, (err, rows) => {
      console.log(t.name + ':', JSON.stringify(rows, null, 2));
    });
  });
});
" 2>/dev/null

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t=>t.name));
for (const t of tables) {
  const rows = db.prepare('SELECT * FROM ' + t.name).all();
  if (rows.length > 0) {
    console.log('\n=== ' + t.name + ' (' + rows.length + ' rows) ===');
    const sample = rows.filter(r => {
      const s = JSON.stringify(r).toLowerCase();
      return s.includes('coffee') || s.includes('sofia') || s.includes('follow') || s.includes('remind') || s.includes('4:30');
    });
    if (sample.length > 0) {
      console.log('MATCHED:', JSON.stringify(sample, null, 2));
    } else {
      console.log('No matches for coffee/sofia/follow/remind/4:30');
    }
  }
}
"

